// downPacket converts a packet of v2193 whose layout v2169 changed to the packet
// of v2169 of its ID, false for a packet of another ID.
func downPacket(pk proto.Packet) (proto.Packet, bool) {
	switch pk := pk.(type) {
	case *v2193.InventoryTransactionPacket:
		return downInventoryTransactionPacket(pk), true
	case *v2193.BossEventPacket:
		return downBossEventPacket(pk), true
	case *v2193.PlaySoundPacket:
		return downPlaySoundPacket(pk), true
	case *v2193.MoveActorDeltaPacket:
		return downMoveActorDeltaPacket(pk), true
	case *v2193.PlayerAuthInputPacket:
		return downPlayerAuthInputPacket(pk), true
	case *v2193.ItemStackResponsePacket:
		return downItemStackResponsePacket(pk), true
	case *v2193.SubChunkPacket:
		return downSubChunkPacket(pk), true
	case *v2193.DimensionDataPacket:
		return downDimensionDataPacket(pk), true
	case *v2193.CameraPresetsPacket:
		return downCameraPresetsPacket(pk), true
	case *v2193.ServerBoundDiagnosticsPacket:
		return downServerBoundDiagnosticsPacket(pk), true
	case *v2193.PrimitiveShapesPacket:
		return downPrimitiveShapesPacket(pk), true
	case *v2193.ServerBoundPackSettingChangePacket:
		return downServerBoundPackSettingChangePacket(pk), true
	case *v2193.ClientBoundAttributeLayerSyncPacket:
		return downClientBoundAttributeLayerSyncPacket(pk), true
	}
	return nil, false
}

